from pathlib import Path
from datetime import date, timedelta
import re
import csv

reference_date = date(2025, 8, 12)
severities = ['ERROR', 'WARNING', 'INFO']
counts = {}

for path in sorted(Path('/app/logs').glob('*.log')):
    match = re.fullmatch(r'(\d{4}-\d{2}-\d{2})_.+\.log', path.name)
    if not match:
        continue
    log_date = date.fromisoformat(match.group(1))
    for line in path.read_text(encoding='utf-8').splitlines():
        severity_match = re.search(r'\[(ERROR|WARNING|INFO)\]', line)
        if not severity_match:
            continue
        severity = severity_match.group(1)
        key = (log_date, severity)
        counts[key] = counts.get(key, 0) + 1

last_7_days = {reference_date - timedelta(days=day) for day in range(6, -1, -1)}
last_30_days = {reference_date - timedelta(days=day) for day in range(29, -1, -1)}
month_start = date(reference_date.year, reference_date.month, 1)
month_to_date = {month_start + timedelta(days=day) for day in range((reference_date - month_start).days + 1)}

def period_count(period_dates, severity):
    return sum(counts.get((event_date, severity), 0) for event_date in period_dates)

with open('/app/summary.csv', 'w', newline='', encoding='utf-8') as output:
    writer = csv.writer(output)
    writer.writerow(['period', 'severity', 'count'])
    for period, period_dates in [
        ('today', {reference_date}),
        ('last_7_days', last_7_days),
        ('last_30_days', last_30_days),
        ('month_to_date', month_to_date),
        ('total', None),
    ]:
        for severity in severities:
            if period == 'total':
                count = sum(counts.get((event_date, severity), 0) for event_date in {d for d, s in counts if s == severity})
            else:
                count = period_count(period_dates, severity)
            writer.writerow([period, severity, count])
